def apply_reviews(questions):
    reviews = {**REVIEWS, **EXTRA_REVIEWS}
    assert set(reviews) == {q['id'] for q in questions}
    for q in questions:
        derivation, reasons, precision, working, sources = reviews[q['id']]
        assert len(reasons) == len(q['options']) == 4
        if q['id'] in STEM_UPDATES:
            q['stem'] = STEM_UPDATES[q['id']]
        for index, text in OPTION_UPDATES.get(q['id'], {}).items():
            q['options'][index] = text
        if q['id'] in TITLES:
            q['title'] = TITLES[q['id']]
        if q['id'] in ('P47','P52'):
            q['revision'] = 2
        if q['id'] == 'P09':
            q['revision'] = 2
            q.pop('old_number', None)
            q['answer_origin'] = 'תרגיל מעובד על בסיס Q148 ו-Q164; הנוסח והפתרון נערכו מחדש ב-17/11/2026'
        q['reviewed'] = '2026-11-17' if q['id'] in ('P09','P13','P47','P52','P57') else '2026-11-14'
        q['option_explanations'] = [
            dict(option=option, correct=i in q['accepted_indices'], reason=reasons[i])
            for i, option in enumerate(q['options'])
        ]
        q['answer_origin'] += (' · ההסבר נבדק ונערך מחדש ב-17/11/2026, כולל כל ארבע החלופות' if q['id'] in ('P09','P13','P47','P52','P57') else ' · ההסבר נבדק ונערך מחדש ב-14/11/2026, כולל כל ארבע החלופות')
        body = '<section class="forecast-review"><h3>דרך הפתרון</h3><p>'+escape(derivation)+'</p>'
        if working:
            body += '<pre>'+escape(working)+'</pre>'
        body += '<h3>למה התשובה נכונה ולמה שאר האפשרויות שגויות</h3><p class="study-source">מזהים כל חלופה לפי הטקסט שלה; אותיות התשובות משתנות בערבוב.</p>'
        for i, item in enumerate(q['option_explanations']):
            label = 'נכונה' if item['correct'] else 'שגויה'
            body += '<div class="option-review" data-option-review="'+str(i)+'"><h4>'+label+' — '+escape(item['option'])+'</h4><p>'+escape(item['reason'])+'</p></div>'
        body += '<h3>דגש והנחות שחשוב לזכור</h3><p>'+escape(precision)+'</p>'
        if sources:
            body += '<p class="study-source">מקורות לבדיקת המנגנון: '+' · '.join('<a href="'+SOURCES[key][1]+'">'+escape(SOURCES[key][0])+'</a>' for key in sources)+'</p>'
        else:
            body += '<p class="study-source">בדיקה: גזירה אלגברית וחישוב עצמאי לפי נתוני השאלה.</p>'
        q['answer_html'] = body+'</section>'
